export interface Task {
  /**
   * A machine-oriented, globally unique identifier with cross-instance scope that can be used to reference this task elsewhere in this or other OSCAL instances. The locally defined UUID of the task can be used to reference the data item locally or globally (e.g., in an imported OSCAL instance). This UUID should be assigned per-subject, which means it should be consistently used to identify the same subject across revisions of the document.
   */
  "uuid": string;
  /**
   * The type of task.
   */
  "type": TaskType;
  /**
   * The title for this task.
   */
  "title": string;
  /**
   * A human-readable description of this task.
   */
  "description"?: string;
  "props"?: Property[];
  "links"?: Link[];
  /**
   * The timing under which the task is intended to occur.
   */
  "timing"?: TaskTiming;
  "dependencies"?: TaskDependency[];
  "tasks"?: Task[];
  "associated-activities"?: TaskAssociatedActivity[];
  "subjects"?: AssessmentSubject[];
  "responsible-roles"?: ResponsibleRole[];
  "remarks"?: string;
}

/**
 * Identifies an individual activity to be performed as part of a task.
 */
export interface TaskAssociatedActivity {
  /**
   * A machine-oriented identifier reference to an activity defined in the list of activities.
   */
  "activity-uuid": string;
  "props"?: Property[];
  "links"?: Link[];
  "responsible-roles"?: ResponsibleRole[];
  "subjects": AssessmentSubject[];
  "remarks"?: string;
}

/**
 * Used to indicate that a task is dependent on another task.
 */
export interface TaskDependency {
  /**
   * A machine-oriented identifier reference to a unique task.
   */
  "task-uuid": string;
  "remarks"?: string;
}

/**
 * The timing under which the task is intended to occur.
 */
export type TaskTiming =
  | TaskTimingWithAtFrequency
  | TaskTimingWithDateRange
  | TaskTimingWithOnDate;

/**
 * The task is intended to occur at the specified frequency.
 */
export interface TaskTimingAtFrequency {
  /**
   * The task must occur after the specified period has elapsed.
   */
  "period": number;
  /**
   * The unit of time for the period.
   */
  "unit": TaskTimingAtFrequencyUnit;
  "remarks"?: string;
}

export type TaskTimingAtFrequencyUnit =
  | "seconds"
  | "minutes"
  | "hours"
  | "days"
  | "months"
  | "years";

/**
 * The task is intended to occur within the specified date range.
 */
export interface TaskTimingDateRange {
  /**
   * The task must occur on or after the specified date.
   */
  "start": string;
  /**
   * The task must occur on or before the specified date.
   */
  "end": string;
  "remarks"?: string;
}

/**
 * The task is intended to occur on the specified date.
 */
export interface TaskTimingOnDate {
  /**
   * The task must occur on the specified date.
   */
  "date": string;
  "remarks"?: string;
}

export interface TaskTimingWithAtFrequency {
  /**
   * The task is intended to occur at the specified frequency.
   */
  "at-frequency": TaskTimingAtFrequency;
  "within-date-range"?: never;
  "on-date"?: never;
}

export interface TaskTimingWithDateRange {
  /**
   * The task is intended to occur within the specified date range.
   */
  "within-date-range": TaskTimingDateRange;
  "at-frequency"?: never;
  "on-date"?: never;
}

export interface TaskTimingWithOnDate {
  /**
   * The task is intended to occur on the specified date.
   */
  "on-date": TaskTimingOnDate;
  "at-frequency"?: never;
  "within-date-range"?: never;
}

export type TaskType =
  | "milestone"
  | "action"
  | (string & {});

/**
 * A telephone service number as defined by ITU-T E.164.
 */
export interface TelephoneNumber {
  /**
   * Indicates the type of phone number.
   */
  "type"?: TelephoneNumberType;
  "number": string;
}

export type TelephoneNumberType =
  | "home"
  | "office"
  | "mobile"
  | (string & {});

/**
 * A pointer, by ID, to an externally-defined threat.
 */
export interface ThreatId {
  /**
   * Specifies the source of the threat information.
   */
  "system": ThreatIdSystem;
  /**
   * An optional location for the threat data, from which this ID originates.
   */
  "href"?: string;
  "id": string;
}

export type ThreatIdSystem =
  | "http://fedramp.gov"
  | "http://fedramp.gov/ns/oscal"
  | (string & {});
